-- Falcon ID schema baseline (main). Schema only, no data.
-- Generated by hack/schema/regen.sh; do not edit by hand. See README.md.

SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SET check_function_bodies = false;
SET search_path = public;

-- RLS policies target this role; the app connects as it in production.
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'falcon_id_app') THEN
        CREATE ROLE falcon_id_app NOLOGIN;
    END IF;
END
$$;

CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA public;

CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA public;

CREATE TYPE public.tenant_type AS ENUM (
    'customer',
    'internal',
    'trial',
    'partner',
    'demo',
    'personal'
);

CREATE FUNCTION public.assign_user_role_with_expiry(p_user_id uuid, p_role_id uuid, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_assigned_by uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_assignment_id UUID;
BEGIN
    INSERT INTO iam_user_roles (user_id, role_id, expires_at, assigned_by)
    VALUES (p_user_id, p_role_id, p_expires_at, p_assigned_by)
    ON CONFLICT (user_id, role_id) DO UPDATE SET
        expires_at = EXCLUDED.expires_at,
        assigned_at = NOW()
    RETURNING id INTO v_assignment_id;

    RETURN v_assignment_id;
END;
$$;

CREATE FUNCTION public.calculate_retention_due_date(p_record_date timestamp with time zone, p_retention_days integer) RETURNS date
    LANGUAGE sql
    AS $$
    SELECT (p_record_date + (p_retention_days || ' days')::INTERVAL)::DATE;
$$;

CREATE FUNCTION public.cleanup_expired_mfa_records() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM iam_email_verifications WHERE expires_at < NOW() AND verified_at IS NULL;

    DELETE FROM iam_mfa_email_codes WHERE expires_at < NOW();

    DELETE FROM iam_mfa_pending_setup WHERE expires_at < NOW();

    DELETE FROM iam_mfa_recovery_codes WHERE used_at IS NOT NULL AND used_at < NOW() - INTERVAL '90 days';
END;
$$;

CREATE FUNCTION public.cleanup_expired_oauth_data() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM iam_oauth_authorization_codes WHERE expires_at < NOW();

    DELETE FROM iam_oauth_states WHERE expires_at < NOW();

    DELETE FROM iam_oauth_tokens
    WHERE (access_token_expires_at < NOW() - INTERVAL '30 days')
       OR (revoked_at IS NOT NULL AND revoked_at < NOW() - INTERVAL '30 days');
END;
$$;

CREATE FUNCTION public.cleanup_expired_service_account_tokens() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM iam_service_account_tokens WHERE expires_at < NOW() - INTERVAL '7 days';
END;
$$;

CREATE FUNCTION public.cleanup_iam_audit_logs(retention_days integer DEFAULT 730) RETURNS TABLE(deleted_count bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_deleted_count BIGINT;
BEGIN
    DELETE FROM iam_audit_logs
    WHERE created_at < NOW() - (retention_days || ' days')::INTERVAL;

    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

    RETURN QUERY SELECT v_deleted_count;
END;
$$;

