CREATE FUNCTION public.cleanup_password_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    policy_history_count INT;
BEGIN
    SELECT COALESCE(pp.history_count, 5) INTO policy_history_count
    FROM iam_users u
    LEFT JOIN iam_password_policies pp ON pp.tenant_id = u.tenant_id
    WHERE u.id = NEW.user_id;

    DELETE FROM iam_password_history
    WHERE id IN (
        SELECT id FROM iam_password_history
        WHERE user_id = NEW.user_id
        ORDER BY created_at DESC
        OFFSET policy_history_count
    );

    RETURN NEW;
END;
$$;

