BEGIN
    DELETE FROM iam_token_blacklist WHERE expires_at < NOW();
END;
$$;

CREATE FUNCTION public.compute_audit_entry_hash(p_sequence_number bigint, p_tenant_id uuid, p_action character varying, p_created_at timestamp with time zone, p_previous_hash character varying, p_details jsonb) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_hash_input TEXT;
BEGIN
    v_hash_input := COALESCE(p_sequence_number::TEXT, '') || '|' ||
                    COALESCE(p_tenant_id::TEXT, '') || '|' ||
                    COALESCE(p_action, '') || '|' ||
                    COALESCE(p_created_at::TEXT, '') || '|' ||
                    COALESCE(p_previous_hash, '') || '|' ||
                    COALESCE(p_details::TEXT, '{}');

    RETURN encode(digest(v_hash_input, 'sha256'), 'hex');
END;
$$;

CREATE FUNCTION public.compute_email_hash(plain_email text) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN encode(digest(lower(trim(plain_email)), 'sha256'), 'hex');
END;
$$;

CREATE FUNCTION public.create_audit_log_partition(partition_date date) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    partition_name TEXT;
    partition_start DATE;
    partition_end DATE;
BEGIN
    partition_start := date_trunc('month', partition_date);
    partition_end := partition_start + INTERVAL '1 month';
    partition_name := 'iam_audit_log_y' || to_char(partition_start, 'YYYY') || 'm' || to_char(partition_start, 'MM');

    IF NOT EXISTS (SELECT 1 FROM pg_class WHERE relname = partition_name) THEN
        EXECUTE format(
            'CREATE TABLE %I PARTITION OF iam_audit_log_partitioned
             FOR VALUES FROM (%L) TO (%L)',
            partition_name, partition_start, partition_end
        );
        RAISE NOTICE 'Created partition: %', partition_name;
    END IF;
END;
$$;

CREATE FUNCTION public.detect_suspicious_iam_activity(p_tenant_id uuid, p_lookback_hours integer DEFAULT 24, p_denial_threshold integer DEFAULT 10) RETURNS TABLE(actor_id uuid, denial_count bigint, unique_resources bigint, first_denial timestamp with time zone, last_denial timestamp with time zone, sample_actions jsonb)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        al.actor_id,
        COUNT(*)::BIGINT as denial_count,
        COUNT(DISTINCT (al.resource_type || ':' || al.resource_id))::BIGINT as unique_resources,
        MIN(al.created_at) as first_denial,
        MAX(al.created_at) as last_denial,
        jsonb_agg(
            jsonb_build_object(
                'action', al.action,
                'resource', al.resource_type || ':' || al.resource_id,
                'time', al.created_at
            ) ORDER BY al.created_at DESC
        ) FILTER (WHERE al.created_at IN (
            SELECT created_at FROM iam_audit_logs
            WHERE actor_id = al.actor_id AND result = 'denied'
            ORDER BY created_at DESC LIMIT 5
        )) as sample_actions
    FROM iam_audit_logs al
    WHERE al.tenant_id = p_tenant_id
        AND al.created_at > NOW() - (p_lookback_hours || ' hours')::INTERVAL
        AND al.result = 'denied'
    GROUP BY al.actor_id
    HAVING COUNT(*) >= p_denial_threshold
    ORDER BY denial_count DESC;
END;
$$;

CREATE FUNCTION public.drop_old_audit_log_partitions(months_to_keep integer DEFAULT 12) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    cutoff_date DATE;
    partition_record RECORD;
    dropped_count INT := 0;
    partition_year INT;
    partition_month INT;
    partition_date DATE;
BEGIN
    cutoff_date := date_trunc('month', CURRENT_DATE) - (months_to_keep || ' months')::INTERVAL;

    FOR partition_record IN
        SELECT c.relname as partition_name
        FROM pg_class c
        JOIN pg_inherits i ON c.oid = i.inhrelid
        JOIN pg_class parent ON i.inhparent = parent.oid
        WHERE parent.relname = 'iam_audit_log_partitioned'
          AND c.relname ~ 'iam_audit_log_y[0-9]{4}m[0-9]{2}'
    LOOP
        partition_year := substring(partition_record.partition_name from 'y([0-9]{4})')::INT;
        partition_month := substring(partition_record.partition_name from 'm([0-9]{2})')::INT;
        partition_date := make_date(partition_year, partition_month, 1);

        IF partition_date < cutoff_date THEN
            EXECUTE format('DROP TABLE %I', partition_record.partition_name);
            dropped_count := dropped_count + 1;
            RAISE NOTICE 'Dropped partition: %', partition_record.partition_name;
        END IF;
    END LOOP;

    RETURN dropped_count;
END;
$$;

CREATE FUNCTION public.expire_old_invitations() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    expired_count INTEGER;
BEGIN
    UPDATE iam_user_invitations
    SET status = 'expired', updated_at = NOW()
    WHERE status = 'pending' AND expires_at < NOW();

    GET DIAGNOSTICS expired_count = ROW_COUNT;
    RETURN expired_count;
END;
$$;

CREATE FUNCTION public.fn_prevent_idp_scope_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.scope IS DISTINCT FROM NEW.scope THEN
        RAISE EXCEPTION 'SECURITY: Cannot change identity provider scope after creation. '
            'Current scope: %, attempted scope: %. '
            'To change scope, delete this provider and recreate it with the desired scope.',
            OLD.scope, NEW.scope
        USING ERRCODE = 'check_violation';
    END IF;

    IF OLD.realm_id IS DISTINCT FROM NEW.realm_id THEN
        RAISE EXCEPTION 'SECURITY: Cannot change identity provider realm_id after creation. '
            'To move a provider to a different realm, delete and recreate it.'
        USING ERRCODE = 'check_violation';
    END IF;

    IF OLD.tenant_id IS DISTINCT FROM NEW.tenant_id THEN
        RAISE EXCEPTION 'SECURITY: Cannot change identity provider tenant_id after creation. '
            'To move a provider to a different tenant, delete and recreate it.'
        USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END;
$$;

CREATE FUNCTION public.fn_set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.get_audit_logs_for_archive(p_tenant_id uuid, p_retention_days integer DEFAULT 365) RETURNS TABLE(id uuid, tenant_id uuid, user_id uuid, action character varying, resource_type character varying, resource_id uuid, details jsonb, ip_address character varying, user_agent text, success boolean, error_message text, correlation_id uuid, target_user_id uuid, created_at timestamp with time zone)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        al.id,
        al.tenant_id,
        al.user_id,
        al.action,
        al.resource_type,
        al.resource_id,
        al.details,
        al.ip_address,
        al.user_agent,
        al.success,
        al.error_message,
        al.correlation_id,
        al.target_user_id,
        al.created_at
    FROM iam_audit_log al
    WHERE al.tenant_id = p_tenant_id
      AND al.archived = false
      AND al.created_at < NOW() - (p_retention_days || ' days')::INTERVAL
    ORDER BY al.created_at;
END;
$$;

CREATE FUNCTION public.get_iam_audit_stats(p_tenant_id uuid DEFAULT NULL::uuid, p_start_date timestamp with time zone DEFAULT (now() - '30 days'::interval), p_end_date timestamp with time zone DEFAULT now()) RETURNS TABLE(total_events bigint, relationship_creates bigint, relationship_deletes bigint, permission_checks bigint, permission_denials bigint, errors bigint, unique_actors bigint, unique_resources bigint, avg_latency_ms numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        COUNT(*)::BIGINT as total_events,
        COUNT(*) FILTER (WHERE action = 'relationship.created')::BIGINT as relationship_creates,
        COUNT(*) FILTER (WHERE action = 'relationship.deleted')::BIGINT as relationship_deletes,
        COUNT(*) FILTER (WHERE action LIKE 'permission.%')::BIGINT as permission_checks,
        COUNT(*) FILTER (WHERE result = 'denied')::BIGINT as permission_denials,
        COUNT(*) FILTER (WHERE result = 'error')::BIGINT as errors,
        COUNT(DISTINCT actor_id)::BIGINT as unique_actors,
        COUNT(DISTINCT (resource_type || ':' || resource_id))::BIGINT as unique_resources,
        ROUND(AVG(latency_ms)::NUMERIC, 2) as avg_latency_ms
    FROM iam_audit_logs
    WHERE created_at BETWEEN p_start_date AND p_end_date
        AND (p_tenant_id IS NULL OR tenant_id = p_tenant_id);
END;
$$;

CREATE FUNCTION public.get_latest_audit_hash(p_tenant_id uuid) RETURNS TABLE(sequence_number bigint, entry_hash character varying)
    LANGUAGE sql
    AS $$
    SELECT sequence_number, entry_hash
    FROM iam_audit_log
    WHERE tenant_id = p_tenant_id
        AND entry_hash IS NOT NULL
    ORDER BY sequence_number DESC
    LIMIT 1;
$$;

CREATE FUNCTION public.get_or_create_device(p_user_id uuid, p_fingerprint_hash text, p_device_name character varying DEFAULT NULL::character varying, p_device_type character varying DEFAULT NULL::character varying, p_browser character varying DEFAULT NULL::character varying, p_os character varying DEFAULT NULL::character varying, p_ip character varying DEFAULT NULL::character varying) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_device_id UUID;
BEGIN
    SELECT id INTO v_device_id
    FROM iam_devices
    WHERE user_id = p_user_id AND fingerprint_hash = p_fingerprint_hash;

    IF v_device_id IS NULL THEN
        INSERT INTO iam_devices (
            user_id, fingerprint_hash, device_name, device_type,
            browser, os, last_ip
        )
        VALUES (
            p_user_id, p_fingerprint_hash, p_device_name, p_device_type,
            p_browser, p_os, p_ip
        )
        RETURNING id INTO v_device_id;
    ELSE
        UPDATE iam_devices
        SET last_seen_at = NOW(),
            last_ip = COALESCE(p_ip, last_ip)
        WHERE id = v_device_id;
    END IF;

    RETURN v_device_id;
END;
$$;

CREATE FUNCTION public.get_organization_ancestors(org_id uuid) RETURNS TABLE(id uuid, name character varying, display_name character varying, level integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    org_path TEXT;
    ancestor_id UUID;
BEGIN
    SELECT path INTO org_path FROM iam_organizations WHERE iam_organizations.id = org_id;

    IF org_path IS NOT NULL THEN
        FOR ancestor_id IN
            SELECT unnest(string_to_array(trim(both '/' from org_path), '/'))::UUID
        LOOP
            IF ancestor_id != org_id THEN
                RETURN QUERY
                SELECT o.id, o.name, o.display_name, o.level
                FROM iam_organizations o
                WHERE o.id = ancestor_id;
            END IF;
        END LOOP;
    END IF;
END;
$$;

CREATE FUNCTION public.get_organization_descendants(org_id uuid) RETURNS TABLE(id uuid, name character varying, display_name character varying, level integer, path text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT o.id, o.name, o.display_name, o.level, o.path
    FROM iam_organizations o
    WHERE o.path LIKE (SELECT path FROM iam_organizations WHERE iam_organizations.id = org_id) || '/%'
    ORDER BY o.path;
END;
$$;

CREATE FUNCTION public.get_platform_permissions(p_user_id uuid) RETURNS TABLE(permission_name character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE
    internal_tenant_id UUID := '00000000-0000-0000-0000-000000000002';
BEGIN
    RETURN QUERY
    SELECT DISTINCT p.name
    FROM iam_users u
    JOIN iam_user_roles ur ON ur.user_id = u.id
    JOIN iam_role_permissions rp ON rp.role_id = ur.role_id
    JOIN iam_permissions p ON p.id = rp.permission_id
    WHERE u.id = p_user_id
      AND u.tenant_id = internal_tenant_id
      AND u.is_active = true
      AND p.module = 'platform'
      AND (ur.expires_at IS NULL OR ur.expires_at > NOW())
    ORDER BY p.name;
END;
$$;

CREATE FUNCTION public.get_user_effective_roles(p_user_id uuid) RETURNS TABLE(role_id uuid, role_name character varying, source character varying, source_id uuid, source_name character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT ur.role_id, r.name, 'direct'::VARCHAR, NULL::UUID, NULL::VARCHAR
    FROM iam_user_roles ur
    JOIN iam_roles r ON r.id = ur.role_id
    WHERE ur.user_id = p_user_id
      AND (ur.expires_at IS NULL OR ur.expires_at > NOW())

    UNION

    SELECT gr.role_id, r.name, 'group'::VARCHAR, gm.group_id, g.name
    FROM iam_group_members gm
    JOIN iam_group_roles gr ON gr.group_id = gm.group_id
    JOIN iam_roles r ON r.id = gr.role_id
    JOIN iam_groups g ON g.id = gm.group_id
    WHERE gm.user_id = p_user_id
      AND (gr.expires_at IS NULL OR gr.expires_at > NOW());
END;
$$;

CREATE FUNCTION public.get_user_iam_permissions(p_user_id uuid) RETURNS TABLE(permission_name character varying, resource character varying, action character varying)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT DISTINCT p.name, p.resource, p.action
    FROM iam_users u
    JOIN iam_user_roles ur ON ur.user_id = u.id
    JOIN iam_role_permissions rp ON rp.role_id = ur.role_id
    JOIN iam_permissions p ON p.id = rp.permission_id
    WHERE u.id = p_user_id
      AND u.is_active = true
      AND p.module = 'iam'
      AND (ur.expires_at IS NULL OR ur.expires_at > NOW())
    ORDER BY p.name;
END;
$$;

CREATE FUNCTION public.has_iam_permission(p_user_id uuid, p_permission_name character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    has_perm BOOLEAN;
BEGIN
    SELECT EXISTS (
        SELECT 1
        FROM iam_users u
        JOIN iam_user_roles ur ON ur.user_id = u.id
        JOIN iam_role_permissions rp ON rp.role_id = ur.role_id
        JOIN iam_permissions p ON p.id = rp.permission_id
        WHERE u.id = p_user_id
          AND u.is_active = true
          AND (ur.expires_at IS NULL OR ur.expires_at > NOW())
          AND (
              p.name = p_permission_name  -- Exact match
              OR p.name = 'iam:*:*'       -- Super admin
              OR (p.name LIKE 'iam:' || SPLIT_PART(p_permission_name, ':', 2) || ':*') -- Resource wildcard
          )
    ) INTO has_perm;

    RETURN has_perm;
END;
$$;

CREATE FUNCTION public.iam_jit_elevation_transitions_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' AND current_setting('app.tenant_purge', true) = 'on' THEN
        RETURN OLD;
    END IF;
    RAISE EXCEPTION 'iam_jit_elevation_transitions is append-only; % is not permitted', TG_OP
        USING ERRCODE = '23514';
END;
$$;

