$$;

CREATE FUNCTION public.iam_oauth_authorization_codes_sync_used() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.used_at IS NOT NULL AND NOT NEW.is_used THEN
        NEW.is_used := TRUE;
    END IF;
    IF NEW.is_used AND NEW.used_at IS NULL THEN
        NEW.used_at := NOW();
    END IF;
    RETURN NEW;
END;
$$;

