CREATE FUNCTION public.iam_platform_roles_enforce() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    user_tenant_id uuid;
    has_active_elevation boolean;
BEGIN
    SELECT tenant_id INTO user_tenant_id FROM iam_users WHERE id = NEW.user_id;

    IF user_tenant_id IS NULL OR user_tenant_id::text <> '00000000-0000-0000-0000-000000000002' THEN
        RAISE EXCEPTION 'iam_platform_roles.user_id must belong to the platform-internal tenant (00000000-0000-0000-0000-000000000002), got tenant %', user_tenant_id
            USING ERRCODE = '23514';
    END IF;

    IF NEW.role_key <> 'platform_viewer' THEN
        SELECT EXISTS (
            SELECT 1 FROM iam_jit_elevations
            WHERE requester_id = NEW.user_id
              AND role_key = NEW.role_key
              AND status = 'active'
              AND expires_at > now()
        ) INTO has_active_elevation;

        IF NOT has_active_elevation THEN
            RAISE EXCEPTION 'role_key % is not standing-assignable; it requires a confirmed, active iam_jit_elevations row (platform_role_not_standing_assignable)', NEW.role_key
                USING ERRCODE = '23514';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;

CREATE FUNCTION public.iam_users_stamp_mfa_totp_enabled_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.mfa_totp_enabled IS NOT TRUE THEN
        NEW.mfa_totp_enabled_at := NULL;
    ELSIF TG_OP = 'INSERT' OR OLD.mfa_totp_enabled IS NOT TRUE THEN
        NEW.mfa_totp_enabled_at := NOW();
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.is_device_trusted(p_user_id uuid, p_fingerprint_hash text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_is_trusted BOOLEAN;
BEGIN
    SELECT is_trusted INTO v_is_trusted
    FROM iam_devices
    WHERE user_id = p_user_id
      AND fingerprint_hash = p_fingerprint_hash
      AND is_trusted = true
      AND (trust_expires_at IS NULL OR trust_expires_at > NOW());

    RETURN COALESCE(v_is_trusted, false);
END;
$$;

CREATE FUNCTION public.is_dsar_overdue(p_deadline_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql
    AS $$
    SELECT p_deadline_at < NOW();
$$;

CREATE FUNCTION public.is_platform_admin(p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    internal_tenant_id UUID := '00000000-0000-0000-0000-000000000002';
    has_permission BOOLEAN;
BEGIN
    SELECT EXISTS (
        SELECT 1 FROM iam_users u
        JOIN iam_user_roles ur ON ur.user_id = u.id
        JOIN iam_role_permissions rp ON rp.role_id = ur.role_id
        JOIN iam_permissions p ON p.id = rp.permission_id
        WHERE u.id = p_user_id
          AND u.tenant_id = internal_tenant_id
          AND u.is_active = true
          AND p.module = 'platform'
          AND (ur.expires_at IS NULL OR ur.expires_at > NOW())
    ) INTO has_permission;

    RETURN has_permission;
END;
$$;

CREATE FUNCTION public.log_consent_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF (TG_OP = 'INSERT') OR (OLD.granted != NEW.granted) THEN
        INSERT INTO iam_consent_history (
            user_id,
            consent_type_id,
            action,
            consent_version,
            ip_address,
            user_agent
        ) VALUES (
            NEW.user_id,
            NEW.consent_type_id,
            CASE WHEN NEW.granted THEN 'granted' ELSE 'revoked' END,
            NEW.consent_version,
            NEW.ip_address,
            NEW.user_agent
        );
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION public.manage_audit_log_partitions() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_month DATE;
BEGIN
    current_month := date_trunc('month', CURRENT_DATE)::DATE;

    PERFORM create_audit_log_partition(current_month);
    PERFORM create_audit_log_partition((current_month + INTERVAL '1 month')::DATE);
    PERFORM create_audit_log_partition((current_month + INTERVAL '2 months')::DATE);
END;
$$;

CREATE FUNCTION public.mark_device_trusted(p_user_id uuid, p_fingerprint_hash text, p_trust_duration_days integer DEFAULT 30) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_updated INT;
BEGIN
    UPDATE iam_devices
    SET is_trusted = true,
        trust_expires_at = NOW() + (p_trust_duration_days || ' days')::INTERVAL,
        updated_at = NOW()
    WHERE user_id = p_user_id
      AND fingerprint_hash = p_fingerprint_hash;

    GET DIAGNOSTICS v_updated = ROW_COUNT;
    RETURN v_updated > 0;
END;
$$;

CREATE FUNCTION public.platform_admin_audit_log_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' AND current_setting('app.tenant_purge', true) = 'on' THEN
        RETURN OLD;
    END IF;
    RAISE EXCEPTION 'platform_admin_audit_log is append-only; % is not permitted', TG_OP
        USING ERRCODE = '23514';
END;
$$;

