CREATE FUNCTION public.revoke_device_trust(p_user_id uuid, p_device_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_revoked INT;
BEGIN
    IF p_device_id IS NOT NULL THEN
        UPDATE iam_devices
        SET is_trusted = false,
            trust_expires_at = NULL,
            updated_at = NOW()
        WHERE id = p_device_id AND user_id = p_user_id;
    ELSE
        UPDATE iam_devices
        SET is_trusted = false,
            trust_expires_at = NULL,
            updated_at = NOW()
        WHERE user_id = p_user_id AND is_trusted = true;
    END IF;

    GET DIAGNOSTICS v_revoked = ROW_COUNT;
    RETURN v_revoked;
END;
$$;

CREATE FUNCTION public.revoke_token_family(p_token_family uuid, p_reason character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    revoked_count INT;
BEGIN
    UPDATE iam_refresh_tokens
    SET revoked_at = NOW(),
        revoked_reason = p_reason
    WHERE token_family = p_token_family
      AND revoked_at IS NULL;

    GET DIAGNOSTICS revoked_count = ROW_COUNT;
    RETURN revoked_count;
END;
$$;

