CREATE FUNCTION public.sync_ad_group_roles(p_tenant_id uuid, p_provider_id uuid, p_user_id uuid, p_ad_groups text[]) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_role_ids UUID[];
    new_role_ids UUID[];
BEGIN
    SELECT ARRAY_AGG(ur.role_id) INTO current_role_ids
    FROM iam_user_roles ur
    WHERE ur.user_id = p_user_id
      AND ur.role_id IN (
          SELECT iam_role_id FROM iam_ad_group_role_mapping
          WHERE tenant_id = p_tenant_id AND provider_id = p_provider_id AND is_active = true
      );

    SELECT ARRAY_AGG(DISTINCT agrm.iam_role_id) INTO new_role_ids
    FROM iam_ad_group_role_mapping agrm
    WHERE agrm.tenant_id = p_tenant_id
      AND agrm.provider_id = p_provider_id
      AND agrm.is_active = true
      AND agrm.ad_group_guid = ANY(p_ad_groups);

    current_role_ids := COALESCE(current_role_ids, ARRAY[]::UUID[]);
    new_role_ids := COALESCE(new_role_ids, ARRAY[]::UUID[]);

    DELETE FROM iam_user_roles
    WHERE user_id = p_user_id
      AND role_id = ANY(current_role_ids)
      AND role_id != ALL(new_role_ids);

    INSERT INTO iam_user_roles (user_id, role_id, assigned_by)
    SELECT p_user_id, role_id, NULL
    FROM UNNEST(new_role_ids) AS role_id
    WHERE role_id != ALL(current_role_ids)
    ON CONFLICT (user_id, role_id) DO NOTHING;
END;
$$;

