CREATE FUNCTION public.update_organization_path() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    parent_path TEXT;
BEGIN
    IF NEW.parent_id IS NULL THEN
        NEW.path := '/' || NEW.id::TEXT;
        NEW.level := 0;
    ELSE
        SELECT path, level INTO parent_path FROM iam_organizations WHERE id = NEW.parent_id;
        IF parent_path IS NOT NULL THEN
            NEW.path := parent_path || '/' || NEW.id::TEXT;
            NEW.level := (SELECT level + 1 FROM iam_organizations WHERE id = NEW.parent_id);
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

