CREATE FUNCTION public.verify_audit_hash_chain(p_tenant_id uuid, p_start_sequence bigint DEFAULT NULL::bigint, p_end_sequence bigint DEFAULT NULL::bigint) RETURNS TABLE(is_valid boolean, total_checked bigint, broken_at_sequence bigint, error_message text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_record RECORD;
    v_expected_hash VARCHAR(64);
    v_total_checked BIGINT := 0;
    v_previous_hash VARCHAR(64) := NULL;
    v_previous_sequence BIGINT := NULL;
BEGIN
    FOR v_record IN
        SELECT
            sequence_number,
            previous_hash,
            entry_hash,
            tenant_id,
            action,
            created_at,
            details
        FROM iam_audit_log
        WHERE tenant_id = p_tenant_id
            AND (p_start_sequence IS NULL OR sequence_number >= p_start_sequence)
            AND (p_end_sequence IS NULL OR sequence_number <= p_end_sequence)
        ORDER BY sequence_number ASC
    LOOP
        v_total_checked := v_total_checked + 1;

        IF v_previous_sequence IS NOT NULL AND v_record.sequence_number != v_previous_sequence + 1 THEN
            RETURN QUERY SELECT
                false,
                v_total_checked,
                v_record.sequence_number,
                format('Sequence gap detected: expected %s, got %s',
                    v_previous_sequence + 1, v_record.sequence_number);
            RETURN;
        END IF;

        IF v_previous_hash IS NOT NULL AND v_record.previous_hash != v_previous_hash THEN
            RETURN QUERY SELECT
                false,
                v_total_checked,
                v_record.sequence_number,
                format('Previous hash mismatch at sequence %s', v_record.sequence_number);
            RETURN;
        END IF;

        v_expected_hash := compute_audit_entry_hash(
            v_record.sequence_number,
            v_record.tenant_id,
            v_record.action,
            v_record.created_at,
            v_record.previous_hash,
            v_record.details
        );

        IF v_record.entry_hash IS NOT NULL AND v_record.entry_hash != v_expected_hash THEN
            RETURN QUERY SELECT
                false,
                v_total_checked,
                v_record.sequence_number,
                format('Entry hash mismatch at sequence %s', v_record.sequence_number);
            RETURN;
        END IF;

        v_previous_hash := v_record.entry_hash;
        v_previous_sequence := v_record.sequence_number;
    END LOOP;

    RETURN QUERY SELECT
        true,
        v_total_checked,
        NULL::BIGINT,
        'Hash chain verified successfully'::TEXT;
END;
$$;

