CREATE TABLE public.iam_jit_elevations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    requester_id uuid NOT NULL,
    role_key text NOT NULL,
    tenant_scope uuid,
    reason text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    approver_id uuid,
    approved_at timestamp with time zone,
    requested_duration_seconds integer NOT NULL,
    expires_at timestamp with time zone,
    is_break_glass boolean DEFAULT false NOT NULL,
    retroactive_approver_id uuid,
    retroactive_approved_at timestamp with time zone,
    break_glass_violation boolean DEFAULT false NOT NULL,
    spicedb_activate_zed_token text,
    spicedb_revoke_zed_token text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT iam_jit_elevations_check CHECK (((approver_id IS NULL) OR (approver_id <> requester_id))),
    CONSTRAINT iam_jit_elevations_check1 CHECK (((retroactive_approver_id IS NULL) OR (retroactive_approver_id <> requester_id))),
    CONSTRAINT iam_jit_elevations_check2 CHECK (((NOT is_break_glass) OR (requested_duration_seconds <= 3600))),
    CONSTRAINT iam_jit_elevations_check3 CHECK (((NOT is_break_glass) OR (approver_id IS NULL))),
    CONSTRAINT iam_jit_elevations_reason_check CHECK ((length(btrim(reason)) > 0)),
    CONSTRAINT iam_jit_elevations_requested_duration_seconds_check CHECK (((requested_duration_seconds > 0) AND (requested_duration_seconds <= 28800))),
    CONSTRAINT iam_jit_elevations_role_key_check CHECK ((role_key = ANY (ARRAY['platform_admin'::text, 'platform_support'::text, 'platform_billing'::text, 'platform_security'::text, 'platform_viewer'::text, 'platform_compliance'::text, 'platform_sre'::text]))),
    CONSTRAINT iam_jit_elevations_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'active'::text, 'expired'::text, 'revoked'::text, 'denied'::text])))
);

