);

CREATE TABLE public.iam_saml_metadata_refresh_logs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    sp_id uuid NOT NULL,
    status character varying NOT NULL,
    changes jsonb,
    error_message text,
    cert_rotated boolean DEFAULT false,
    old_cert_expiry timestamp with time zone,
    new_cert_expiry timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.iam_saml_service_providers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    name character varying NOT NULL,
    entity_id character varying NOT NULL,
    acs_url text NOT NULL,
    slo_url text,
    metadata_url text,
    certificate text,
    name_id_format character varying DEFAULT 'urn:oasis:names:tc:SAML:1.1:nameid-format:emailAddress'::character varying,
    sign_assertions boolean DEFAULT true,
    encrypt_assertions boolean DEFAULT false,
    attribute_mapping jsonb DEFAULT '{"email": "email", "lastName": "last_name", "firstName": "first_name", "displayName": "display_name"}'::jsonb,
    allowed_attributes text[] DEFAULT '{email,firstName,lastName,displayName,groups}'::text[],
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    created_by uuid,
    realm_id uuid,
    raw_metadata_xml text,
    metadata_last_fetched timestamp with time zone,
    metadata_auto_refresh boolean DEFAULT false,
    metadata_refresh_interval_hours integer DEFAULT 24,
    detected_idp_type character varying,
    organization_name character varying,
    certificate_expiry timestamp with time zone,
    metadata_import_source character varying DEFAULT 'manual'::character varying,
    certificate_fingerprint character varying,
    allowed_signature_algorithms text[] DEFAULT ARRAY['http://www.w3.org/2001/04/xmldsig-more#rsa-sha256'::text, 'http://www.w3.org/2001/04/xmldsig-more#rsa-sha384'::text, 'http://www.w3.org/2001/04/xmldsig-more#rsa-sha512'::text],
    require_signed_response boolean DEFAULT true,
    require_signed_assertion boolean DEFAULT true
);

