);

CREATE TABLE public.iam_service_principals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    product_id uuid,
    name text NOT NULL,
    slug text NOT NULL,
    description text DEFAULT ''::text,
    public_key_pem text NOT NULL,
    key_id text NOT NULL,
    allowed_scopes text[] DEFAULT '{}'::text[] NOT NULL,
    ip_allowlist inet[] DEFAULT '{}'::inet[],
    status text DEFAULT 'active'::text NOT NULL,
    last_authenticated_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    auto_provisioned boolean DEFAULT false NOT NULL,
    bootstrap_token_hash text,
    previous_public_key_pem text,
    previous_key_id text,
    key_rotated_at timestamp with time zone,
    key_grace_period_ends_at timestamp with time zone,
    heartbeat_interval_seconds integer DEFAULT 300 NOT NULL,
    last_heartbeat_at timestamp with time zone,
    auto_suspend_after_missed integer DEFAULT 3 NOT NULL,
    type character varying DEFAULT 'legacy'::character varying,
    application_id uuid,
    tenant_id uuid,
    display_name_override character varying,
    oauth_client_id uuid,
    installation_status character varying DEFAULT 'enabled'::character varying,
    scope_overrides text[],
    token_lifetime_override jsonb,
    deleted_at timestamp with time zone,
    purge_after timestamp with time zone
);

CREATE TABLE public.iam_sessions (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
