    user_agent text,
    location character varying,
    is_active boolean DEFAULT true,
    created_at timestamp with time zone DEFAULT now(),
    last_activity_at timestamp with time zone DEFAULT now(),
    expires_at timestamp with time zone NOT NULL,
    ended_at timestamp with time zone,
    end_reason character varying,
    impersonator_id uuid,
    impersonation_session_id uuid,
    is_trusted boolean DEFAULT false,
    device_id character varying,
    realm_id uuid,
    realm_slug character varying,
    saml_provider_id uuid,
    saml_name_id character varying,
    saml_session_index character varying,
    max_expires_at timestamp with time zone DEFAULT (now() + '30 days'::interval) NOT NULL,
    tenant_id uuid,
    idp_id uuid,
    idp_scope character varying,
    authenticated_at timestamp with time zone,
    previous_session_id uuid,
    session_regenerated boolean DEFAULT false,
    auth_methods_used text[] DEFAULT '{}'::text[] NOT NULL,
    country_code character varying,
    asn integer,
    asn_org character varying(255),
    city character varying(255),
    region character varying(255),
    is_vpn_hint boolean
);

CREATE TABLE public.iam_settings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid DEFAULT '00000000-0000-0000-0000-000000000001'::uuid NOT NULL,
    hr_ldap_enabled boolean DEFAULT true NOT NULL,
    hr_ldap_server character varying DEFAULT ''::character varying NOT NULL,
    hr_ldap_port integer DEFAULT 389 NOT NULL,
    hr_ldap_use_tls boolean DEFAULT false NOT NULL,
    hr_ldap_bind_dn character varying DEFAULT ''::character varying NOT NULL,
    hr_ldap_bind_password character varying DEFAULT ''::character varying NOT NULL,
    hr_ldap_base_dn character varying DEFAULT ''::character varying NOT NULL,
    hr_ldap_user_filter character varying DEFAULT '(&(objectClass=user)(objectCategory=person))'::character varying NOT NULL,
    hr_ldap_group_base_dn character varying DEFAULT ''::character varying NOT NULL,
    hr_ldap_group_filter character varying DEFAULT '(objectClass=group)'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_by uuid,
    abac_enabled boolean DEFAULT false NOT NULL,
    abac_fallback_rbac boolean DEFAULT true NOT NULL,
    role_expiration_enabled boolean DEFAULT true NOT NULL
);

CREATE TABLE public.iam_siem_export_log (
