    event_type_filter text[] DEFAULT '{}'::text[] NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    export_format text DEFAULT 'json'::text NOT NULL,
    protocol text DEFAULT 'https_webhook'::text NOT NULL,
    include_audit_logs boolean DEFAULT false NOT NULL,
    include_threat_events boolean DEFAULT true NOT NULL,
    batch_interval_minutes integer DEFAULT 5 NOT NULL,
    s3_bucket text,
    s3_prefix text,
    s3_region text,
    syslog_facility integer DEFAULT 16 NOT NULL,
    syslog_port integer DEFAULT 514 NOT NULL,
    last_export_at timestamp with time zone,
    last_export_status text,
    total_events_exported bigint DEFAULT 0 NOT NULL,
    total_export_failures bigint DEFAULT 0 NOT NULL
);

