    company_name character varying,
    company_slug character varying,
    verification_token character varying NOT NULL,
    verified boolean DEFAULT false NOT NULL,
    verified_at timestamp with time zone,
    completed boolean DEFAULT false NOT NULL,
    completed_at timestamp with time zone,
    tenant_id uuid,
    user_id uuid,
    ip_address character varying,
    user_agent text,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    continuation text,
    completion_secret_hash text,
    verification_code_hash text,
    verification_code_expires_at timestamp with time zone,
    verification_attempts integer DEFAULT 0 NOT NULL,
    verification_failed_total integer DEFAULT 0 NOT NULL,
    verification_resends integer DEFAULT 0 NOT NULL,
    verification_resend_window_start timestamp with time zone,
    verification_last_sent_at timestamp with time zone,
    CONSTRAINT iam_signup_requests_continuation_len_check CHECK (((continuation IS NULL) OR (char_length(continuation) <= 4096)))
);

CREATE TABLE public.iam_sod_rules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid,
    module text NOT NULL,
    permission_a text NOT NULL,
    permission_b text NOT NULL,
    mode text DEFAULT 'warn'::text NOT NULL,
    description text,
    is_default boolean DEFAULT false NOT NULL,
    created_by uuid,
    disabled_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT iam_sod_rules_check CHECK ((permission_a <> permission_b)),
    CONSTRAINT iam_sod_rules_mode_check CHECK ((mode = ANY (ARRAY['warn'::text, 'block'::text])))
);

