    role_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    invited_by uuid NOT NULL,
    token text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '7 days'::interval) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    accepted_at timestamp with time zone,
    email_normalized text GENERATED ALWAYS AS (lower(btrim(email))) STORED NOT NULL,
    seat_class text DEFAULT 'member'::text NOT NULL,
    last_resent_at timestamp with time zone,
    CONSTRAINT iam_team_invitations_seat_class_check CHECK ((seat_class = ANY (ARRAY['member'::text, 'external'::text, 'service'::text]))),
    CONSTRAINT iam_team_invitations_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'accepted'::text, 'expired'::text, 'revoked'::text, 'declined'::text])))
);

