);

CREATE TABLE public.iam_tenant_hosts (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    host character varying NOT NULL,
    tenant_id uuid NOT NULL,
    canonical_url character varying NOT NULL,
    status character varying DEFAULT 'pending_verification'::character varying NOT NULL,
    verification_token character varying NOT NULL,
    verification_method character varying DEFAULT 'txt'::character varying NOT NULL,
    verified_at timestamp with time zone,
    last_verified_at timestamp with time zone,
    verification_failures integer DEFAULT 0 NOT NULL,
    default_client_id character varying,
    branding_override jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT iam_tenant_hosts_active_implies_verified CHECK ((((status)::text <> 'active'::text) OR (verified_at IS NOT NULL))),
    CONSTRAINT iam_tenant_hosts_status_check CHECK (((status)::text = ANY (ARRAY[('pending_verification'::character varying)::text, ('active'::character varying)::text, ('suspended'::character varying)::text]))),
    CONSTRAINT iam_tenant_hosts_token_min_length CHECK ((char_length((verification_token)::text) >= 32)),
    CONSTRAINT iam_tenant_hosts_verification_method_check CHECK (((verification_method)::text = ANY (ARRAY[('txt'::character varying)::text, ('cname'::character varying)::text, ('http01'::character varying)::text])))
);

