CREATE MATERIALIZED VIEW public.mv_login_analytics AS
 SELECT tenant_id,
    date_trunc('hour'::text, created_at) AS hour_bucket,
    date_trunc('day'::text, created_at) AS day_bucket,
    count(*) FILTER (WHERE (((action)::text = 'login'::text) AND (success = true))) AS successful_logins,
    count(*) FILTER (WHERE (((action)::text = 'login'::text) AND (success = false))) AS failed_logins,
    count(*) FILTER (WHERE ((action)::text = 'logout'::text)) AS logouts,
    count(DISTINCT user_id) FILTER (WHERE (((action)::text = 'login'::text) AND (success = true))) AS unique_users,
    count(DISTINCT ip_address) FILTER (WHERE ((action)::text = 'login'::text)) AS unique_ips,
    count(*) FILTER (WHERE ((action)::text = 'password_change'::text)) AS password_changes,
    count(*) FILTER (WHERE ((action)::text = 'mfa_verify'::text)) AS mfa_verifications
   FROM public.iam_audit_log
  WHERE ((created_at > (now() - '90 days'::interval)) AND ((action)::text = ANY (ARRAY[('login'::character varying)::text, ('logout'::character varying)::text, ('password_change'::character varying)::text, ('mfa_verify'::character varying)::text, ('password_reset'::character varying)::text])))
  GROUP BY tenant_id, (date_trunc('hour'::text, created_at)), (date_trunc('day'::text, created_at))
  WITH NO DATA;

CREATE MATERIALIZED VIEW public.mv_tenant_statistics AS
 SELECT t.id AS tenant_id,
    t.name AS tenant_name,
    t.status AS tenant_status,
    count(DISTINCT u.id) AS total_users,
    count(DISTINCT u.id) FILTER (WHERE (u.is_active = true)) AS active_users,
    count(DISTINCT u.id) FILTER (WHERE (u.is_locked = true)) AS locked_users,
    count(DISTINCT u.id) FILTER (WHERE (u.mfa_enabled = true)) AS mfa_enabled_users,
    count(DISTINCT s.id) FILTER (WHERE ((s.is_active = true) AND (s.expires_at > now()))) AS active_sessions,
    count(DISTINCT r.id) AS total_roles,
    count(DISTINCT g.id) AS total_groups
   FROM ((((public.iam_tenants t
     LEFT JOIN public.iam_users u ON ((t.id = u.tenant_id)))
     LEFT JOIN public.iam_sessions s ON ((u.id = s.user_id)))
     LEFT JOIN public.iam_roles r ON ((t.id = r.tenant_id)))
     LEFT JOIN public.iam_groups g ON ((t.id = g.tenant_id)))
  GROUP BY t.id, t.name, t.status
  WITH NO DATA;

CREATE MATERIALIZED VIEW public.mv_user_activity_summary AS
 SELECT u.id AS user_id,
    u.tenant_id,
    u.username,
    u.email,
    u.last_login_at,
    u.created_at AS user_created_at,
    count(DISTINCT s.id) FILTER (WHERE (s.is_active = true)) AS active_sessions,
    count(DISTINCT s.id) AS total_sessions,
    max(s.last_activity_at) AS last_activity,
    count(DISTINCT al.id) FILTER (WHERE (((al.action)::text = 'login'::text) AND (al.success = true) AND (al.created_at > (now() - '30 days'::interval)))) AS logins_last_30_days,
    count(DISTINCT al.id) FILTER (WHERE (((al.action)::text = 'login'::text) AND (al.success = false) AND (al.created_at > (now() - '30 days'::interval)))) AS failed_logins_last_30_days,
    u.is_active,
    u.is_locked,
    u.mfa_enabled
   FROM ((public.iam_users u
     LEFT JOIN public.iam_sessions s ON ((u.id = s.user_id)))
     LEFT JOIN public.iam_audit_log al ON (((u.id = al.user_id) AND (al.created_at > (now() - '30 days'::interval)))))
  GROUP BY u.id, u.tenant_id, u.username, u.email, u.last_login_at, u.created_at, u.is_active, u.is_locked, u.mfa_enabled
  WITH NO DATA;

CREATE MATERIALIZED VIEW public.mv_user_permissions AS
 SELECT DISTINCT u.id AS user_id,
    u.tenant_id,
    p.id AS permission_id,
    p.name AS permission_name,
    p.module,
    p.resource,
    p.action,
    'direct'::text AS source
   FROM (((public.iam_users u
     JOIN public.iam_user_roles ur ON (((u.id = ur.user_id) AND ((ur.expires_at IS NULL) OR (ur.expires_at > now())))))
     JOIN public.iam_role_permissions rp ON ((ur.role_id = rp.role_id)))
     JOIN public.iam_permissions p ON ((rp.permission_id = p.id)))
UNION
 SELECT DISTINCT gm.user_id,
    u.tenant_id,
    p.id AS permission_id,
    p.name AS permission_name,
    p.module,
    p.resource,
    p.action,
    'group'::text AS source
   FROM ((((public.iam_group_members gm
     JOIN public.iam_users u ON ((gm.user_id = u.id)))
     JOIN public.iam_group_roles gr ON ((gm.group_id = gr.group_id)))
     JOIN public.iam_role_permissions rp ON ((gr.role_id = rp.role_id)))
     JOIN public.iam_permissions p ON ((rp.permission_id = p.id)))
  WITH NO DATA;

CREATE TABLE public.ops_approval_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    action text NOT NULL,
    resource text NOT NULL,
    audience text NOT NULL,
    payload_sha256 text NOT NULL,
    reason text NOT NULL,
    requester_id uuid NOT NULL,
    approver_id uuid,
    status text DEFAULT 'pending'::text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    decided_at timestamp with time zone,
    used_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    reason_code text,
    decision_note text,
    tenant_id uuid,
    CONSTRAINT ops_approval_requests_action_check CHECK ((length(btrim(action)) > 0)),
    CONSTRAINT ops_approval_requests_audience_check CHECK ((length(btrim(audience)) > 0)),
    CONSTRAINT ops_approval_requests_payload_sha256_check CHECK ((payload_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ops_approval_requests_reason_check CHECK ((length(btrim(reason)) > 0)),
    CONSTRAINT ops_approval_requests_resource_check CHECK ((length(btrim(resource)) > 0)),
    CONSTRAINT ops_approval_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'expired'::text, 'consumed'::text, 'cancelled'::text]))),
    CONSTRAINT ops_approval_requests_two_person_check CHECK (((approver_id IS NULL) OR (approver_id <> requester_id))),
    CONSTRAINT ops_approval_requests_used_requires_approver_check CHECK (((used_at IS NULL) OR (approver_id IS NOT NULL)))
);

