    password_require_special boolean DEFAULT false NOT NULL,
    password_special_chars character varying DEFAULT '!@#$%^&*()_+-=[]{}|;:,.<>?'::character varying,
    password_max_age_days integer DEFAULT 90,
    password_history_count integer DEFAULT 5,
    password_min_age_hours integer DEFAULT 0,
    mfa_required boolean DEFAULT false NOT NULL,
    mfa_required_for_admins boolean DEFAULT true NOT NULL,
    mfa_methods jsonb DEFAULT '["totp", "email"]'::jsonb NOT NULL,
    mfa_grace_period_days integer DEFAULT 7,
    mfa_remember_device_days integer DEFAULT 30,
    session_max_lifetime_hours integer DEFAULT 24 NOT NULL,
    session_idle_timeout_minutes integer DEFAULT 30 NOT NULL,
    session_absolute_timeout_hours integer DEFAULT 168,
    concurrent_sessions_limit integer DEFAULT 5,
    single_session_per_device boolean DEFAULT false NOT NULL,
    max_failed_attempts integer DEFAULT 5 NOT NULL,
    lockout_duration_minutes integer DEFAULT 30 NOT NULL,
    lockout_threshold_window_minutes integer DEFAULT 15 NOT NULL,
    progressive_lockout boolean DEFAULT true NOT NULL,
    ip_whitelist jsonb,
    ip_blacklist jsonb,
    geo_restrictions jsonb,
    risk_authentication_enabled boolean DEFAULT false NOT NULL,
    risk_threshold_low integer DEFAULT 30 NOT NULL,
    risk_threshold_medium integer DEFAULT 60 NOT NULL,
    risk_threshold_high integer DEFAULT 80 NOT NULL,
    audit_retention_days integer DEFAULT 365 NOT NULL,
    audit_log_failed_logins boolean DEFAULT true NOT NULL,
    audit_log_successful_logins boolean DEFAULT true NOT NULL,
    audit_log_admin_actions boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    refresh_token_rotation_grace_seconds integer,
    mfa_enrollment_max_skips integer DEFAULT 0 NOT NULL
);

CREATE TABLE public.realm_tenants (
    realm_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    assigned_at timestamp with time zone DEFAULT now() NOT NULL,
    assigned_by uuid,
    previous_realm_id uuid,
    migrated_at timestamp with time zone
);

CREATE TABLE public.realms (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    slug character varying NOT NULL,
    display_name character varying NOT NULL,
    type character varying DEFAULT 'shared'::character varying NOT NULL,
    status character varying DEFAULT 'active'::character varying NOT NULL,
    database_connection_id uuid,
    schema_name character varying,
    settings jsonb DEFAULT '{}'::jsonb NOT NULL,
    branding jsonb DEFAULT '{"logo_url": null, "custom_css": null, "favicon_url": null, "primary_color": "#4F46E5", "secondary_color": "#10B981", "login_background_url": null}'::jsonb NOT NULL,
    max_tenants integer,
    max_users_per_tenant integer,
    max_total_users integer,
    features jsonb DEFAULT '{"api_access": true, "custom_domain": false, "mfa_available": true, "sso_available": true, "advanced_audit": false}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid
);

CREATE TABLE public.sla_definitions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    plan_tier character varying NOT NULL,
    service_name character varying NOT NULL,
    metric_type character varying NOT NULL,
    target_value numeric NOT NULL,
    unit character varying NOT NULL,
    target_uptime_percent numeric,
    max_response_time_ms integer,
    max_downtime_minutes_monthly integer,
    support_response_hours integer,
    support_channels text[],
    penalties jsonb,
    measurement_period character varying DEFAULT 'monthly'::character varying,
    is_active boolean DEFAULT true,
    effective_from date DEFAULT CURRENT_DATE,
    effective_until date,
    metadata jsonb,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);

CREATE TABLE public.tenant_domains (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    domain character varying NOT NULL,
    tenant_id uuid NOT NULL,
    verified boolean DEFAULT false,
    verification_token character varying,
    verification_method character varying DEFAULT 'dns_txt'::character varying,
    discovery_policy character varying DEFAULT 'managed'::character varying NOT NULL,
    federated_idp_url text,
    federated_idp_type character varying,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.tenant_quotas (
    tenant_id uuid NOT NULL,
    subscription_tier character varying DEFAULT 'free'::character varying NOT NULL,
    api_requests_per_minute integer DEFAULT 60 NOT NULL,
    api_requests_per_hour integer DEFAULT 1000 NOT NULL,
    api_requests_per_day integer DEFAULT 10000 NOT NULL,
    auth_attempts_per_minute integer DEFAULT 10 NOT NULL,
    token_refresh_per_minute integer DEFAULT 30 NOT NULL,
    burst_multiplier numeric DEFAULT 1.0 NOT NULL,
    custom_limits jsonb,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid
);

CREATE TABLE public.tenant_seat_counters (
    tenant_id uuid NOT NULL,
    seats_used integer DEFAULT 0 NOT NULL,
    seats_pending integer DEFAULT 0 NOT NULL,
    seat_limit integer,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    seat_limit_version bigint,
    seat_limit_computed_at timestamp with time zone,
    CONSTRAINT tenant_seat_counters_seat_limit_check CHECK (((seat_limit IS NULL) OR (seat_limit >= 0))),
    CONSTRAINT tenant_seat_counters_seats_pending_check CHECK ((seats_pending >= 0)),
    CONSTRAINT tenant_seat_counters_seats_used_check CHECK ((seats_used >= 0))
);

ALTER TABLE ONLY public.tenant_seat_counters FORCE ROW LEVEL SECURITY;

CREATE TABLE public.user_bulk_operations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    initiated_by uuid NOT NULL,
    initiated_by_username character varying,
    operation_type character varying NOT NULL,
    total_records integer DEFAULT 0 NOT NULL,
    processed_records integer DEFAULT 0 NOT NULL,
    successful_records integer DEFAULT 0 NOT NULL,
    failed_records integer DEFAULT 0 NOT NULL,
    status character varying DEFAULT 'pending'::character varying NOT NULL,
    input_file_url text,
    output_file_url text,
    error_file_url text,
    options jsonb DEFAULT '{}'::jsonb,
    errors jsonb DEFAULT '[]'::jsonb,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now()
);

CREATE TABLE public.workload_identity_providers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    name character varying NOT NULL,
    provider_type character varying NOT NULL,
    issuer_url text NOT NULL,
    audience_match text,
    subject_mapping text,
    jwks_endpoint text,
    allowed_subjects text[] DEFAULT '{}'::text[] NOT NULL,
    role_bindings text[] DEFAULT '{}'::text[] NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid
);

